js='  var TIPS={\n'+',\n'.join('    %s:{t:%s,p:%s,l:%s}'%(k,json.dumps(t,ensure_ascii=False),json.dumps(p,ensure_ascii=False),json.dumps(l,ensure_ascii=False)) for k,t,p,l in TIPS)+'\n  };'
for f in ('tpl_movil.html','tpl_portatil.html','tips.js.part'):
    s=open(f).read(); i=s.index('  var TIPS={'); j=s.index('\n  };',i)+5
    old=set(re.findall(r'^    (\w+):\{t:',s[i:j],re.M)); new={k for k,*_ in TIPS}; assert old==new,(f,old^new)
    open(f,'w').write(s[:i]+js+s[j:])
print('tips ok',len(TIPS))
